<?php
require_once 'includes/functions.php'; require_login();
if($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); require_admin(); $action=$_POST['action']??''; if($action==='save') { $id=(int)($_POST['id']??0); $data=[trim($_POST['name']??''),trim($_POST['category']??''),trim($_POST['supplier']??''),(float)($_POST['price']??0),(int)($_POST['quantity']??0),trim($_POST['barcode']??'')]; if($data[0]===''||$data[3]<0||$data[4]<0){flash('Enter valid product details.','error');} else if($id){$q=db()->prepare('UPDATE products SET name=?,category=?,supplier=?,price=?,quantity=?,barcode=? WHERE id=?');$q->execute([...$data,$id]);flash('Product updated.');}else{$q=db()->prepare('INSERT INTO products(name,category,supplier,price,quantity,barcode) VALUES(?,?,?,?,?,?)');$q->execute($data);flash('Product added.');} } elseif($action==='delete'){ $q=db()->prepare('DELETE FROM products WHERE id=?');$q->execute([(int)$_POST['id']]);flash('Product deleted.');} redirect('products.php'); }
$edit=null; if(isset($_GET['edit'])){$q=db()->prepare('SELECT * FROM products WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$search=trim($_GET['q']??'');$q=db()->prepare('SELECT * FROM products WHERE name LIKE ? OR category LIKE ? OR barcode LIKE ? ORDER BY name');$like="%$search%";$q->execute([$like,$like,$like]);$products=$q->fetchAll();
$page_title='Products'; require 'includes/header.php'; ?>
<div class="panel"><div class="panel-head"><h1>Product &amp; Inventory Management</h1><?php if($_SESSION['user']['role']==='admin'): ?><a class="button" href="#product-form">Add product</a><?php endif; ?></div><form class="search" method="get"><input name="q" placeholder="Search name, category or barcode" value="<?= e($search) ?>"><button class="button secondary">Search</button></form><div class="table-wrap"><table><tr><th>Product</th><th>Category</th><th>Supplier</th><th>Price</th><th>Stock</th><th>Barcode</th><?php if($_SESSION['user']['role']==='admin'): ?><th>Actions</th><?php endif; ?></tr><?php foreach($products as $p): ?><tr><td><?= e($p['name']) ?></td><td><?= e($p['category']) ?></td><td><?= e($p['supplier']) ?></td><td><?= money($p['price']) ?></td><td><span class="<?= $p['quantity']<=5?'low':'' ?>"><?= (int)$p['quantity'] ?></span></td><td><?= e($p['barcode']) ?></td><?php if($_SESSION['user']['role']==='admin'): ?><td class="actions"><a href="?edit=<?= (int)$p['id'] ?>">Edit</a><form method="post" onsubmit="return confirm('Delete this product?')"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button class="link danger">Delete</button></form></td><?php endif; ?></tr><?php endforeach; ?><?php if(!$products): ?><tr><td colspan="7">No products found.</td></tr><?php endif; ?></table></div></div>
<?php if($_SESSION['user']['role']==='admin'): ?><div class="panel" id="product-form"><h2><?= $edit?'Update product':'Add new product' ?></h2><form method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label>Product name<input name="name" required value="<?= e($edit['name']??'') ?>"></label><label>Category<input name="category" value="<?= e($edit['category']??'') ?>"></label><label>Supplier<input name="supplier" value="<?= e($edit['supplier']??'') ?>"></label><label>Price (₹)<input type="number" name="price" min="0" step="0.01" required value="<?= e($edit['price']??'') ?>"></label><label>Quantity<input type="number" name="quantity" min="0" required value="<?= e($edit['quantity']??'0') ?>"></label><label>Barcode<input name="barcode" value="<?= e($edit['barcode']??'') ?>"></label><div><button class="button">Save product</button> <a class="button secondary" href="products.php">Cancel</a></div></form></div><?php endif; ?>
<?php require 'includes/footer.php'; ?>
